 95	static bool NormalizeVec(const cv::Vec3d &v, cv::Vec3d &out) {
 96	  double n = std::sqrt(v.dot(v));
 97	  if (n < 1e-6) {
 98	    return false;
 99	  }
100	  out = v / n;
101	  return true;
102	}
