104	static cv::Vec4d RotationMatrixToQuaternion(const cv::Mat &R) {
105	  cv::Vec4d q(1.0, 0.0, 0.0, 0.0);
106	  if (R.empty()) {
107	    return q;
108	  }
109	  double trace = R.at<double>(0, 0) + R.at<double>(1, 1) + R.at<double>(2, 2);
110	  if (trace > 0.0) {
111	    double s = std::sqrt(trace + 1.0) * 2.0;
112	    q[0] = 0.25 * s;
113	    q[1] = (R.at<double>(2, 1) - R.at<double>(1, 2)) / s;
114	    q[2] = (R.at<double>(0, 2) - R.at<double>(2, 0)) / s;
115	    q[3] = (R.at<double>(1, 0) - R.at<double>(0, 1)) / s;
116	  } else {
117	    if (R.at<double>(0, 0) > R.at<double>(1, 1) &&
118	        R.at<double>(0, 0) > R.at<double>(2, 2)) {
119	      double s = std::sqrt(1.0 + R.at<double>(0, 0) - R.at<double>(1, 1) - R.at<double>(2, 2)) * 2.0;
120	      q[0] = (R.at<double>(2, 1) - R.at<double>(1, 2)) / s;
121	      q[1] = 0.25 * s;
122	      q[2] = (R.at<double>(0, 1) + R.at<double>(1, 0)) / s;
123	      q[3] = (R.at<double>(0, 2) + R.at<double>(2, 0)) / s;
124	    } else if (R.at<double>(1, 1) > R.at<double>(2, 2)) {
125	      double s = std::sqrt(1.0 + R.at<double>(1, 1) - R.at<double>(0, 0) - R.at<double>(2, 2)) * 2.0;
126	      q[0] = (R.at<double>(0, 2) - R.at<double>(2, 0)) / s;
127	      q[1] = (R.at<double>(0, 1) + R.at<double>(1, 0)) / s;
128	      q[2] = 0.25 * s;
129	      q[3] = (R.at<double>(1, 2) + R.at<double>(2, 1)) / s;
130	    } else {
131	      double s = std::sqrt(1.0 + R.at<double>(2, 2) - R.at<double>(0, 0) - R.at<double>(1, 1)) * 2.0;
132	      q[0] = (R.at<double>(1, 0) - R.at<double>(0, 1)) / s;
133	      q[1] = (R.at<double>(0, 2) + R.at<double>(2, 0)) / s;
134	      q[2] = (R.at<double>(1, 2) + R.at<double>(2, 1)) / s;
135	      q[3] = 0.25 * s;
136	    }
137	  }
138	  return q;
139	}
