141	static cv::Vec3d RotationMatrixToEulerXYZ(const cv::Mat &R) {
142	  if (R.empty()) {
143	    return cv::Vec3d(0.0, 0.0, 0.0);
144	  }
145	  double r00 = R.at<double>(0, 0);
146	  double r10 = R.at<double>(1, 0);
147	  double r20 = R.at<double>(2, 0);
148	  double r21 = R.at<double>(2, 1);
149	  double r22 = R.at<double>(2, 2);
150	
151	  double pitch = std::asin(std::max(-1.0, std::min(1.0, -r20)));
152	  double roll = std::atan2(r21, r22);
153	  double yaw = std::atan2(r10, r00);
154	  return cv::Vec3d(roll, pitch, yaw);
155	}
