157	static bool ProjectPoint(const cv::Point3d &p_cam, const cv::Mat &K, cv::Point &out) {
158	  if (p_cam.z <= 0.0 || K.empty()) {
159	    return false;
160	  }
161	  cv::Mat pt_cam = (cv::Mat_<double>(3, 1) << p_cam.x, p_cam.y, p_cam.z);
162	  cv::Mat pt_img = K * pt_cam / p_cam.z;
163	  out = cv::Point(static_cast<int>(pt_img.at<double>(0, 0)),
164	                  static_cast<int>(pt_img.at<double>(1, 0)));
165	  return true;
166	}
