181	static bool GetKpCam(const PoseResult &pose,
182	                     const Pose3DInfo &info,
183	                     int idx,
184	                     float min_conf,
185	                     cv::Point3d &out) {
186	  if (idx < 0 || idx >= static_cast<int>(info.kp_cam.size())) {
187	    return false;
188	  }
189	  if (!info.kp_valid[idx]) {
190	    return false;
191	  }
192	  if (pose.keypoints[idx].confidence < min_conf) {
193	    return false;
194	  }
195	  out = info.kp_cam[idx];
196	  return true;
197	}
