199	static bool AngleDeg(const cv::Vec3d &a, const cv::Vec3d &b, double &out_deg) {
200	  double na = std::sqrt(a.dot(a));
201	  double nb = std::sqrt(b.dot(b));
202	  if (na < 1e-6 || nb < 1e-6) {
203	    return false;
204	  }
205	  double cosv = a.dot(b) / (na * nb);
206	  cosv = std::max(-1.0, std::min(1.0, cosv));
207	  out_deg = std::acos(cosv) * (180.0 / M_PI);
208	  return true;
209	}
