211	static std::string ClassifyPosture(double tt_deg, double ts_deg) {
212	  if (tt_deg <= 135.0) {
213	    if (ts_deg <= 135.0) {
214	      return "Tuck";
215	    }
216	    return "Pike";
217	  }
218	  return "Straight";
219	}
