295	static void DrawBodyFrameBox(cv::Mat &image,
296	                             const cv::Mat &R_body_cam,
297	                             const cv::Point3d &center_cam,
298	                             double half_x,
299	                             double half_y,
300	                             double half_z,
301	                             const cv::Mat &K) {
302	  if (R_body_cam.empty() || K.empty()) {
303	    return;
304	  }
305	
306	  std::array<cv::Point3d, 8> corners_body = {
307	      cv::Point3d(-half_x, -half_y, -half_z),
308	      cv::Point3d(half_x, -half_y, -half_z),
309	      cv::Point3d(half_x, half_y, -half_z),
310	      cv::Point3d(-half_x, half_y, -half_z),
311	      cv::Point3d(-half_x, -half_y, half_z),
312	      cv::Point3d(half_x, -half_y, half_z),
313	      cv::Point3d(half_x, half_y, half_z),
314	      cv::Point3d(-half_x, half_y, half_z)
315	  };
316	
317	  std::array<cv::Point, 8> corners_2d;
318	  std::array<bool, 8> visible{};
319	
320	  for (size_t i = 0; i < corners_body.size(); ++i) {
321	    const cv::Point3d &p_body = corners_body[i];
322	    cv::Point3d p_cam(
323	        center_cam.x + R_body_cam.at<double>(0, 0) * p_body.x +
324	            R_body_cam.at<double>(0, 1) * p_body.y + R_body_cam.at<double>(0, 2) * p_body.z,
325	        center_cam.y + R_body_cam.at<double>(1, 0) * p_body.x +
326	            R_body_cam.at<double>(1, 1) * p_body.y + R_body_cam.at<double>(1, 2) * p_body.z,
327	        center_cam.z + R_body_cam.at<double>(2, 0) * p_body.x +
328	            R_body_cam.at<double>(2, 1) * p_body.y + R_body_cam.at<double>(2, 2) * p_body.z);
329	    visible[i] = ProjectPoint(p_cam, K, corners_2d[i]);
330	  }
331	
332	  auto draw_edge = [&](int a, int b) {
333	    if (visible[a] && visible[b]) {
334	      cv::line(image, corners_2d[a], corners_2d[b], cv::Scalar(0, 200, 255), 2, cv::LINE_AA);
335	    }
336	  };
337	
338	  draw_edge(0, 1);
339	  draw_edge(1, 2);
340	  draw_edge(2, 3);
341	  draw_edge(3, 0);
342	  draw_edge(4, 5);
343	  draw_edge(5, 6);
344	  draw_edge(6, 7);
345	  draw_edge(7, 4);
346	  draw_edge(0, 4);
347	  draw_edge(1, 5);
348	  draw_edge(2, 6);
349	  draw_edge(3, 7);
350	}
