445	int main(int argc, char **argv) {
446	  (void)argc;
447	
448	  // Check model file
449	  std::string model_path = "models/yolov8m-pose-1280.onnx";
450	  if (argc > 1) {
451	    model_path = argv[1];
452	  }
453	
454	  std::cout << "\n=== YOLO Pose Detection with INDEMIND Left Camera ===\n" << std::endl;
455	  std::cout << "Using: Left camera RGB image only (no depth processing)" << std::endl;
456	
457	  // Initialize IMSEE SDK
458	  auto m_pSDK = new CIMRSDK();
459	  MRCONFIG config = {0};
460	  config.bSlam = false;
461	  config.imgResolution = IMG_1280;
462	  config.imgFrequency = 50;
463	  config.imuFrequency = 0;  // Disabled for performance
464	
465	  std::cout << "\nInitializing INDEMIND camera..." << std::endl;
466	  bool init_result = m_pSDK->Init(config);
467	  if (!init_result) {
468	    std::cerr << "ERROR: Failed to initialize INDEMIND SDK!" << std::endl;
469	    delete m_pSDK;
470	    return -1;
471	  }
472	
473	  // Get camera intrinsics and build intrinsic matrix for 3D calculation
474	  auto module_params = m_pSDK->GetModuleParams();
475	  auto param = module_params._left_camera[RESOLUTION::RES_1280X800];
476	
477	  // Debug: print raw parameter values
478	  std::cout << "\nDEBUG: Raw camera parameters:" << std::endl;
479	  std::cout << "  K[0]=" << param._K[0] << ", K[4]=" << param._K[4] << std::endl;
480	  std::cout << "  K[2]=" << param._K[2] << ", K[5]=" << param._K[5] << std::endl;
481	  cv_in_left = cv::Mat::eye(3, 3, CV_64F);
482	  cv_in_left.at<double>(0, 0) = param._K[0];  // fx
483	  cv_in_left.at<double>(1, 1) = param._K[4];  // fy
484	  cv_in_left.at<double>(0, 2) = param._K[2];  // cx
485	  cv_in_left.at<double>(1, 2) = param._K[5];  // cy
486	  cv_in_left_inv = cv_in_left.inv();
487	
488	  std::cout << "\nLeft Camera Intrinsics:" << std::endl;
