221	static PostureMetrics ComputePostureMetrics(const PoseResult &pose,
222	                                            const Pose3DInfo &info) {
223	  PostureMetrics metrics;
224	
225	  const float min_conf = 0.3f;
226	  cv::Point3d lh, rh, ls, rs;
227	  bool lh_ok = GetKpCam(pose, info, LEFT_HIP, min_conf, lh);
228	  bool rh_ok = GetKpCam(pose, info, RIGHT_HIP, min_conf, rh);
229	  bool ls_ok = GetKpCam(pose, info, LEFT_SHOULDER, min_conf, ls);
230	  bool rs_ok = GetKpCam(pose, info, RIGHT_SHOULDER, min_conf, rs);
231	
232	  if (!(lh_ok && rh_ok && ls_ok && rs_ok)) {
233	    return metrics;
234	  }
235	
236	  cv::Point3d hip_mid(0.5 * (lh.x + rh.x),
237	                      0.5 * (lh.y + rh.y),
238	                      0.5 * (lh.z + rh.z));
239	  cv::Point3d sh_mid(0.5 * (ls.x + rs.x),
240	                     0.5 * (ls.y + rs.y),
241	                     0.5 * (ls.z + rs.z));
242	  cv::Vec3d trunk(sh_mid.x - hip_mid.x, sh_mid.y - hip_mid.y, sh_mid.z - hip_mid.z);
243	
244	  cv::Point3d lk, la, rk, ra;
245	  bool lk_ok = GetKpCam(pose, info, LEFT_KNEE, min_conf, lk);
246	  bool la_ok = GetKpCam(pose, info, LEFT_ANKLE, min_conf, la);
247	  bool rk_ok = GetKpCam(pose, info, RIGHT_KNEE, min_conf, rk);
248	  bool ra_ok = GetKpCam(pose, info, RIGHT_ANKLE, min_conf, ra);
249	
250	  if (lh_ok && lk_ok && la_ok) {
251	    cv::Vec3d thigh(lk.x - lh.x, lk.y - lh.y, lk.z - lh.z);
252	    cv::Vec3d shank(la.x - lk.x, la.y - lk.y, la.z - lk.z);
253	    metrics.left_valid =
254	        AngleDeg(trunk, thigh, metrics.left_tt) &&
255	        AngleDeg(thigh, shank, metrics.left_ts);
256	  }
257	
258	  if (rh_ok && rk_ok && ra_ok) {
259	    cv::Vec3d thigh(rk.x - rh.x, rk.y - rh.y, rk.z - rh.z);
260	    cv::Vec3d shank(ra.x - rk.x, ra.y - rk.y, ra.z - rk.z);
261	    metrics.right_valid =
262	        AngleDeg(trunk, thigh, metrics.right_tt) &&
263	        AngleDeg(thigh, shank, metrics.right_ts);
264	  }

264	  }
265	
266	  if (metrics.left_valid && metrics.right_valid) {
267	    metrics.avg_tt = 0.5 * (metrics.left_tt + metrics.right_tt);
268	    metrics.avg_ts = 0.5 * (metrics.left_ts + metrics.right_ts);
269	    metrics.avg_valid = true;
270	  } else if (metrics.left_valid) {
271	    metrics.avg_tt = metrics.left_tt;
272	    metrics.avg_ts = metrics.left_ts;
273	    metrics.avg_valid = true;
274	  } else if (metrics.right_valid) {
275	    metrics.avg_tt = metrics.right_tt;
276	    metrics.avg_ts = metrics.right_ts;
277	    metrics.avg_valid = true;
278	  }
279	
280	  if (metrics.left_valid && metrics.right_valid) {
281	    const std::string left_label = ClassifyPosture(metrics.left_tt, metrics.left_ts);
282	    const std::string right_label = ClassifyPosture(metrics.right_tt, metrics.right_ts);
283	    if (left_label == right_label) {
284	      metrics.label = left_label;
285	    }
286	  } else if (metrics.left_valid) {
287	    metrics.label = ClassifyPosture(metrics.left_tt, metrics.left_ts);
288	  } else if (metrics.right_valid) {
289	    metrics.label = ClassifyPosture(metrics.right_tt, metrics.right_ts);
290	  }
291	
292	  return metrics;
293	}
